sys_script_include.script:
var CatalogRequestLoadScript3 = Class.create();
CatalogRequestLoadScript3.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getReqItemData: function() {
        var ritmID = this.getParameter("req_item_id");
        var ritm = new GlideRecord("sc_req_item");
        ritm.get(ritmID);
        var oVariables = {};

        for (var key in ritm.variables) {
            oVariables[key] = ritm.variables[key] + " ;";
        }

        return JSON.stringify(oVariables);
    },
    type: 'CatalogRequestLoadScript3'
});
